import{_ as a,o as i,c as o,a2 as s}from"./chunks/framework.CgxQ0r6v.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_I/Lineas_de_Investigacion_PNFI.md","filePath":"materias/Proyecto_Sociotecnologico_I/Lineas_de_Investigacion_PNFI.md"}'),n={name:"materias/Proyecto_Sociotecnologico_I/Lineas_de_Investigacion_PNFI.md"};function r(t,e,l,c,d,p){return i(),o("div",null,[...e[0]||(e[0]=[s('<p>3 Gobjemo Bolivariano | N is igol Pogor Popular</p><p>UNIVERSIDAD POLITECNICA TERRITORIAL DEL ESTADO (ez “MARIO BRICENO IRAGORRY”</p><h2 id="lineas-de-investigacion-del-programa-nacional-de-formacion-de-informatica" tabindex="-1">LINEAS DE INVESTIGACION DEL PROGRAMA NACIONAL DE FORMACION DE INFORMATICA <a class="header-anchor" href="#lineas-de-investigacion-del-programa-nacional-de-formacion-de-informatica" aria-label="Permalink to &quot;LINEAS DE INVESTIGACION DEL PROGRAMA NACIONAL DE FORMACION DE INFORMATICA&quot;">​</a></h2><h2 id="campo-de-la-investigacion-informatica" tabindex="-1">CAMPO DE LA INVESTIGACION: INFORMATICA <a class="header-anchor" href="#campo-de-la-investigacion-informatica" aria-label="Permalink to &quot;CAMPO DE LA INVESTIGACION: INFORMATICA&quot;">​</a></h2><p>La informatica se define como la ciencia del tratamiento automatico de la informacioén a través de un computador <s>.</s> Ciencia de la informacién automatizada, todo aquello que tiene relaci6n con el procesamiento de datos, utilizando los computadores y/o los equipos de procesos automaticos de informacion <s>.</s></p><h2 id="area-de-conocimiento-informatica-aplicada" tabindex="-1">AREA DE CONOCIMIENTO: INFORMATICA APLICADA <a class="header-anchor" href="#area-de-conocimiento-informatica-aplicada" aria-label="Permalink to &quot;AREA DE CONOCIMIENTO: INFORMATICA APLICADA&quot;">​</a></h2><p>La Informatica Aplicada, concebida como campo de investigacion, se orienta al estudio, diseno y evaluacion de soluciones tecnolégicas que responden a necesidades concretas en contextos organizacionales, educativos y sociales <s>.</s> En este sentido, Villacis (2024), afirma que ‘la informatica aplicada permite integrar herramientas esenciales para alcanzar una formacion integral, mediante el uso estratégico de tecnologias en contextos reales” (p <s>.</s> 4) <s>.</s> Por su parte, Cevallos et al <s>.</s> (2024), “las tendencias actuales en el uso de la informatica en los procesos de gestion evolucionan constantemente, centrandose en la inteligencia artificial, la computacién en nube, la automatizacion y la informatica de nueva generacién” (p <s>.</s> 463) <s>.</s></p><p>En este sentido, la Informatica Aplicada se consolida como una disciplina transversal que articula conocimientos en programacion, arquitectura de sistemas, gestidn de datos y tecnologias emergentes, con el fin de disefhar soluciones funcionales, seguras y adaptables. Ademas, su aplicacion permite optimizar procesos, fortalecer la toma de decisiones y generar impacto en el contexto actual, posicionandola como motor de transformaci6n digital y desarrollo sostenible.</p><h2 id="linea-de-investigacion-sistemas-de-informacion" tabindex="-1">LINEA DE INVESTIGACION: SISTEMAS DE INFORMACION <a class="header-anchor" href="#linea-de-investigacion-sistemas-de-informacion" aria-label="Permalink to &quot;LINEA DE INVESTIGACION: SISTEMAS DE INFORMACION&quot;">​</a></h2><h2 id="objetivo-general" tabindex="-1">Objetivo General <a class="header-anchor" href="#objetivo-general" aria-label="Permalink to &quot;Objetivo General&quot;">​</a></h2><p>Desarrollar y gestionar sistemas de informacion orientados a resolver necesidades del ambito social mediante soluciones tecnoldgicas eficaces <s>.</s></p><p>GBB desorjoroVenezuelaBotivarano|;,paraislesla Educaciondol Peder UniversitariaPopular</p><p>UNIVERSIDAD POLITECNICATRUJILLOTERRITORIAL DEL ESTADO (ez “MARIO BRICENO IRAGORRY”</p><h2 id="objetivos-especificos" tabindex="-1">Objetivos Especificos <a class="header-anchor" href="#objetivos-especificos" aria-label="Permalink to &quot;Objetivos Especificos&quot;">​</a></h2><ul><li><p>e Mejorar los métodos y procedimientos actuales en las organizaciones a través del uso de sistemas de informacién automatizados <s>.</s></p></li><li><p>e Aplicar metodologias, tecnicas y herramientas para el desarrollo de sistemas de informacion <s>.</s></p></li><li><p>e Fortalecer la integraci6n sector productivo <s>—</s> educativo desarrollando sistemas de informacion que apoyen las actividades de una empresa o negocio y permitan poner en practica en el estudiante los conocimientos adquiridos durante proceso de formacion.</p></li><li><p>e Desarrollar procesos que permitan la eficiente ejecucion de sistemas de informacion nuevos oO pre <s>-</s> existentes en las organizaciones <s>.</s></p></li><li><p>e Aplicar tecnicas y herramientas para la migracion de sistemas de informacion <s>.</s></p></li></ul><h2 id="sistematizacion-de-la-linea-dimensiones-operativas-o-programas" tabindex="-1">Sistematizacion de la linea (Dimensiones operativas o programas) <a class="header-anchor" href="#sistematizacion-de-la-linea-dimensiones-operativas-o-programas" aria-label="Permalink to &quot;Sistematizacion de la linea (Dimensiones operativas o programas)&quot;">​</a></h2><ul><li><p>« Sistemas de informacion tradicionales: esta constituido por un conjunto de elementos de naturaleza diversa que incluyen: equipos, recursos humanos (usuario), datos e informacién y programas y aplicaciones; que interactuan entre si dentro de una organizacion con el fin de apoyar las actividades y funciones que cumplan con los objetivos propuestos de la misma.</p></li><li><p>« Sistemas de informaci6n con propiedades geograficas: son sistemas que permiten evaluar propiedades geograficas de un entorno, generando informacion referente a una entidad geografica desplegando imagenes e informaci6én en un hipermapa</p></li><li><p>« Sistemas de informacion web: son primeramente sistemas de informacién que para su desarrollo se debe considerar la misma disciplina de construcci6n de sistemas de informaci6n no Web exitososy de calidad, sirven para integrar procesos o sistemas dentro de una sola interfaz y a ellos se puede acceder por medio de una Intranet local o por la red global Internet van mas alla de ser un conjunto de paginas Web <s>.</s></p></li></ul><p>GBB desorjoroVenezuelaBotivarano|;,paraislesla Educaciondol PederPopular</p><p>UNIVERSIDAD POLITECNICATRUJILLOTERRITORIAL DEL ESTADO (ez “MARIO BRICENO IRAGORRY”</p><p>la Universitaria</p><ul><li><p>«= Sistemas de informacion colaborativos: son sistemas donde se pueden expresar ideas, experiencias, definiciones, entre otros; los cuales constituyen una red de distribucion de la informacion en una organizacion o entre organizaciones <s>.</s></p></li><li><p>«= Gestion tecnoldgica: procesos relacionados con la implantacion de sistemas, tales como, verificar e instalar nuevos equipos, entrenar a los usuarios, instalar nuevas aplicaciones, agregar nuevos moddulos, ademas de comprobar el correcto funcionamiento de los componentes de un sistema de informaci6n que puede abarcar auditorias, tecnicas de control, evaluacion de la calidad <s>.</s></p></li></ul><h2 id="linea-de-investigacion-desarrollo-de-aplicaciones" tabindex="-1">LINEA DE INVESTIGACION: DESARROLLO DE APLICACIONES <a class="header-anchor" href="#linea-de-investigacion-desarrollo-de-aplicaciones" aria-label="Permalink to &quot;LINEA DE INVESTIGACION: DESARROLLO DE APLICACIONES&quot;">​</a></h2><h2 id="objetivo-general-1" tabindex="-1">Objetivo General <a class="header-anchor" href="#objetivo-general-1" aria-label="Permalink to &quot;Objetivo General&quot;">​</a></h2><p>Desarrollar aplicaciones informaticas que respondan a las necesidades de gestion, control e intercambio de informacion en diversos entornos organizacionales, educativos y sociales, mediante el uso de tecnologias multiplataforma y arquitecturas orientadas a servicios, tanto en entornos locales como distribuidos <s>.</s></p><h2 id="objetivos-especificos-1" tabindex="-1">Objetivos Especificos <a class="header-anchor" href="#objetivos-especificos-1" aria-label="Permalink to &quot;Objetivos Especificos&quot;">​</a></h2><p>° Disefiar y construir productos de software funcionales que puedan ser desplegados en entornos de escritorio, mdoviles, web o hibridos, segun los requerimientos del contexto <s>.</s></p><p>° Desarrollar aplicaciones dinamicas que interactuen con sistemas gestores de bases de datos relacionales y no relacionales, garantizando eficiencia, seguridad y escalabilidad <s>.</s> ° Implementar soluciones que favorezcan la integraci6n, interoperabilidad y portabilidad de las aplicaciones en diferentes plataformas y sistemas operativos. ° Fomentar la participacién de estudiantes y docentes en proyectos de investigacién aplicada que involucren el uso de tecnologias emergentes, metodologias agiles y buenas practicas de desarrollo de software <s>.</s></p><h2 id="sistematizacion-de-la-linea-dimensiones-operativas-0-programas" tabindex="-1">Sistematizacion de la linea (Dimensiones operativas 0 programas) <a class="header-anchor" href="#sistematizacion-de-la-linea-dimensiones-operativas-0-programas" aria-label="Permalink to &quot;Sistematizacion de la linea (Dimensiones operativas 0 programas)&quot;">​</a></h2><ul><li>e Aplicaciones cliente <s>-</s> servidor: desarrollo de sistemas distribuidos que separan responsabilidades entre clientes que solicitan servicios y servidores que los proporcionan <s>.</s> Esta arquitectura permite escalabilidad, modularidad y eficiencia en el procesamiento de datos, facilitando la cooperaciéon entre procesos en redes locales o remotas <s>.</s></li></ul><p>3 GcebiemoVenezuela Bolivariano| Minisjoriopara la Educaciondel Poder PopularUniversitaria</p><p>UNIVERSIDAD POLITECNICAJILLOTERRITORIAL DEL ESTADO (ez “MARIO BRICENO IRAGORRY”</p><ul><li><p>e Servicios de integracion para aplicaciones: implementacion de tecnologias estandar (REST, SOAP, JSON, XML) que permiten la interoperabilidad entre sistemas heterogéneos <s>.</s> Se promueve el uso de arquitecturas orientadas a servicios (SOA) y microservicios, facilitando la evoluci6n, escalabilidad y mantenimiento de las aplicaciones <s>.</s></p></li><li><p>e Aplicaciones multiplataforma: diseno y desarrollo de soluciones que pueden ejecutarse en distintos entornos (web, movil, escritorio, hibrido), utilizando frameworks como Flutter, React Native o Electron <s>.</s> Esta dimension favorece la portabilidad, la eficiencia en el mantenimiento y la cobertura de usuarios diversos <s>.</s></p></li><li><p>e Aplicaciones web interactivas: desarrollo de soluciones accesibles desde navegadores, que permiten interaccion dinamica con el usuario, conexidn con bases de datos y despliegue en entornos de Internet o Intranet <s>.</s> Se utilizan tecnologias como HTML, CSS, JavaScript, frameworks como Angular, React o Vue, y arquitecturas modernas como JAMstack o MVC <s>.</s></p></li><li><p>e Aplicaciones moviles y ubicuas: desarrollo de soluciones adaptadas a dispositivos moviles y contextos de movilidad, integrando sensores, geolocalizacién, notificaciones y conectividad <s>.</s> Se promueve la experiencia de usuario y el acceso remoto a servicios en tiempo real.</p></li><li><p>e Modeladoy gestion de datos: disefo conceptual, ldgico y[fisico][de][estructuras] de[datos] que sustentan el funcionamiento de las aplicaciones, Incluye el uso de modelos entidad <s>-r</s> elacion, normalizacion, diseno de esquemas relacionales y no relacionales, asi como la implementacion en sistemas gestores de bases de datos <s>.</s> Esta dimension garantiza la integridad, consistencia y eficiencia en el almacenamiento, recuperacion y procesamiento de la informacion.</p></li><li><p>e Seguridad y auditoria de aplicaciones: incorporacion de practicas de desarrollo seguro, autenticaci6n, autorizacion, cifrado y trazabilidad <s>.</s> Se abordan normativas como ISO/IEC 27001 y principios de privacidad por diseno, garantizando la integridad y confidencialidad de los sistemas.</p></li></ul><h2 id="linea-de-investigacion-edumatica" tabindex="-1">LINEA DE INVESTIGACION: EDUMATICA <a class="header-anchor" href="#linea-de-investigacion-edumatica" aria-label="Permalink to &quot;LINEA DE INVESTIGACION: EDUMATICA&quot;">​</a></h2><h2 id="objetivo-general-2" tabindex="-1">Objetivo General <a class="header-anchor" href="#objetivo-general-2" aria-label="Permalink to &quot;Objetivo General&quot;">​</a></h2><p>Aplicar las Tecnologias de la Informacion y Comunicacion (TIC) para apoyar el proceso de aprendizaje, y asi contribuir al mejoramiento de la educacion en todos sus niveles</p><p>GBB sorjoroe VenezuelaBotivarano|;,paraingla Educaciondel Poder PoplinUniversitaria</p><p>UNIVERSIDAD POLITECNICAJILLOTERRITORIAL DEL ESTADO (ez “MARIO BRICENO IRAGORRY”</p><h2 id="objetivos-especificos-2" tabindex="-1">Objetivos Especificos <a class="header-anchor" href="#objetivos-especificos-2" aria-label="Permalink to &quot;Objetivos Especificos&quot;">​</a></h2><ul><li><p>e Generar productos de software para incorporarlos en los ambientes de aprendizaje o a la busqueda de logros de caracter pedagdégico y didactico, con el fin de apoyar estrategias de ensenanza y aprendizaje <s>.</s></p></li><li><p>e Generar productos de software en ambientes virtuales, mediados con informatica y telematica, para apoyar y mejorar el proceso educativo <s>.</s></p></li><li><p>e Producir investigacién sobre la mediacion tecnoldgica en los procesos académicos y educativos donde las herramientas informaticas soporten actividades en ambientes de aprendizaje.</p></li><li><p>e Proveer a estudiantes y docentes la oportunidad de realizar proyectos de investigacion que involucren el uso de_ tecnologias’ informaticas en el proceso de ensefnanza <s>-a</s> prendizaje <s>.</s></p></li></ul><h2 id="sistematizacion-de-la-linea-dimensiones-operativas-o-programas-1" tabindex="-1">Sistematizacion de la linea (Dimensiones operativas o programas) <a class="header-anchor" href="#sistematizacion-de-la-linea-dimensiones-operativas-o-programas-1" aria-label="Permalink to &quot;Sistematizacion de la linea (Dimensiones operativas o programas)&quot;">​</a></h2><ul><li><p>e Software educativo: el software educativo son programas para el computador creados con la finalidad especifica de ser utilizados como medio didactico, es decir, para facilitar los procesos de ensefanza y de aprendizaje <s>.</s> El desarrollo de software educativo es una actividad que combina conocimientos de diversa indole: educacional, para fundamentar y estructurar los ambientes de aprendizaje que se crearan con apoyo del software; comunicacional, para fundamentar y estructurar las interfaces hombre <s>-</s> maquina a través de las cuales se llevara la interacci6n entre las personas y los programas, dentro de esquemas multimediales dialogales, lo que conlleva que sean altamente interactivos; informatico, para fundamentar y estructurar la informacion multimedia que se maneja y la ldgica de la interacciédn que orienta el programa <s>.</s> Al estar fundamentada en principios cientificos esta actividad de analizar, disefar, desarrollar, probar y ajustar, poner en marcha y evaluar ambientes de aprendizaje apoyados en informatica, se habla de ingenieria de software educativo multimedial y altamente interactivo <s>.</s></p></li><li><p>e Guias de estudio web: las guias de estudio web representan un material instruccional utilizados para cursos de educacion a distancia y como complemento a la educacién presencial, lo cual provee una estructura para un curso <s>.</s> Representan una herramienta</p></li></ul><p>GBB desorjoroVenezuelaBotivarano|;,paraislesla Educaciondol PederPopular</p><p>UNIVERSIDAD POLITECNICATRUJILLOTERRITORIAL DEL ESTADO (ez “MARIO BRICENO IRAGORRY”</p><p>la Universitaria</p><p>que puede enlazar objetivos, contenidos, procedimientos de evaluacion de aprendizaje, medios y tecnologias utilizadas, entre otros <s>.</s></p><ul><li><p>e Tutoriales: son programas que en mayor o menor medida dirigen el trabajo de los alumnos. Pretenden que, a partir de unas informaciones y mediante la realizacién de ciertas actividades previstas de antemano, los estudiantes pongan en juego determinadas capacidades y aprendan o refuercen unos conocimientos y/o habilidades <s>.</s></p></li><li><p>e Juegos didacticos: el juego puede cumplir al menos tres funciones en el proceso de aprendizaje, al constituirse en un medio de exploracion y expresion, un instrumento para la organizacion y aplicacidn de habilidades y, un factor de socializacion e integracion <s>.</s> La nocion de espacio ludico para la estimulaci6n y organizacion del conocimiento, potencializado por el uso creativo de los recursos de la tecnologia de la informacion y las telecomunicaciones, es una herramienta educativa importante <s>.</s> El juego es también un apoyo con fines de motivacion, diagndstico y evaluacidn, ademas de servir para propiciar la creacion de productos educativos <s>.</s></p></li><li><p>e Entornos interactivos de ensenanza: podemos enmarcar dentro de este programa a los proyectos donde el profesor y los alumnos se encuentran en lugares fisicamente distintos durante el desarrollo 0 exposicién del material de una clase <s>.</s> El proceso de ensefnanza <s>-a</s> prendizaje se lleva a cabo a través de Internet, en cualquier momento y en cualquier lugar <s>.</s> Los proyectos deben crear nuevos escenarios educativos utilizando las tecnologias de informaci6n y comunicacién, necesariamente involucrando a Internet como el enlace entre el transmisor y receptor; ademas la administracion y gerencia de estos nuevos escenarios virtuales también deben formar parte de estos proyectos.</p></li><li><p>e Sistemas e <s>-</s> learning: en este programa encontraremos aquellos programas que faciliten la creacion, adopcion y distribuci6n de contenidos, asi como la adaptacion del ritmo de aprendizaje y la disponibilidad de las herramientas de aprendizaje independientemente de limites horarios o geograficos <s>.</s></p></li></ul><h2 id="linea-de-investigacion-redes-y-telecomunicaciones" tabindex="-1">LINEA DE INVESTIGACION: REDES Y TELECOMUNICACIONES <a class="header-anchor" href="#linea-de-investigacion-redes-y-telecomunicaciones" aria-label="Permalink to &quot;LINEA DE INVESTIGACION: REDES Y TELECOMUNICACIONES&quot;">​</a></h2><h2 id="objetivo-general-3" tabindex="-1">Objetivo General <a class="header-anchor" href="#objetivo-general-3" aria-label="Permalink to &quot;Objetivo General&quot;">​</a></h2><p>Desarrollar aplicaciones que permitan analizar, verificar y simular la transmision de datos, como también la detecci6n de fallas dentro de una red <s>.</s></p><p>fe UNVERSDADROLTECMCATERRITORUL DEL ESTADO {YF “MARIO BRICENO IRAGORRY”</p><p>GO cero totaan ceasing,</p><h2 id="objetivos-especificos-3" tabindex="-1">Objetivos Especificos <a class="header-anchor" href="#objetivos-especificos-3" aria-label="Permalink to &quot;Objetivos Especificos&quot;">​</a></h2><ul><li><p>e Producir software de simulaci6n o aplicacion para verificar y/o simular el comportamiento de la informacion dentro de las redes de transmision de datos, el comportamiento de las sefnales electromagnéticas, la deteccion de fallas, entre otros <s>.</s></p></li><li><p>e Disefnar, apropiacion, desarrollo y gestion de software y hardware aplicados a las telecomunicaciones <s>.</s></p></li><li><p>e Realizar valoraci6n técnica, financiera y ambiental de proyectos de telecomunicaciones <s>.</s></p></li><li><p>e Realizar gestion de proyectos en el area de telecomunicaciones <s>.</s></p></li><li><p>e Disefar, desarrollo y gestion de servicios de valor agregado necesarios para el progreso de la region <s>.</s></p></li></ul><h2 id="sistematizacion-de-la-linea-dimensiones-operativas-o-programas-2" tabindex="-1">Sistematizacion de la linea (Dimensiones operativas o programas) <a class="header-anchor" href="#sistematizacion-de-la-linea-dimensiones-operativas-o-programas-2" aria-label="Permalink to &quot;Sistematizacion de la linea (Dimensiones operativas o programas)&quot;">​</a></h2><ul><li><p>e Simulacion y herramientas de simulacion: la simulacion ha sido utilizada a lo largo de décadas en multitud de areas de la ciencia y la técnica <s>.</s> Antes de iniciar el desarrollo de cualquier sistema complejo, los ingenieros suelen utilizar alguna herramienta de simulacion o test donde sea posible modelizar y probar el sistema que esta desarrollando. Las ventajas de la simulaci6n son multiples: reduccién del tiempo de desarrollo del sistema; chequeo de decisiones a priori, antes de iniciar el desarrollo del proyecto; posibilidad de reutilizacion de un mismo modelo, etc <s>.</s> El uso de simulacion es mas sencillo que otras técnicas analiticas y, por tanto, necesita menos simplificaciones <s>.</s> El modelo y la simulacién tendran como objetivo ayudar a investigadores a modelar dichos sistemas complejos.</p></li><li><p>e Modelos de transmision de datos: se discute la conceptualizacién integral de un sistema de transmisidn desde un marco comun a diferentes tecnologias, tales como: sistemas de comunicaci6on por cable (lineas metalicas u dpticas), radio enlaces fijos, moviles y satelitales <s>.</s> Se describen también aspectos que afectan el desempenio de los sistemas de transmisi6n <s>.</s></p></li></ul><h2 id="linea-de-investigacion-sistemas-inteligentes" tabindex="-1">LINEA DE INVESTIGACION: SISTEMAS INTELIGENTES <a class="header-anchor" href="#linea-de-investigacion-sistemas-inteligentes" aria-label="Permalink to &quot;LINEA DE INVESTIGACION: SISTEMAS INTELIGENTES&quot;">​</a></h2><h2 id="objetivo-general-4" tabindex="-1">Objetivo General <a class="header-anchor" href="#objetivo-general-4" aria-label="Permalink to &quot;Objetivo General&quot;">​</a></h2><p>Desarrollar sistemas y aplicaciones fundamentados en técnicas propias de los Sistemas Inteligentes y sus diversas ramas, mediante el uso de métodos computacionales que permitan</p><p>GBB sorjoroe VenezuelaBotivarano|;,paraingla Educaciondel Poder PoplinUniversitaria</p><p>UNIVERSIDAD POLITECNICAJILLOTERRITORIAL DEL ESTADO (ez “MARIO BRICENO IRAGORRY”</p><p>emular procesos cognitivos humanos como el aprendizaje, la percepcion, el razonamientoy la toma de decisiones.</p><h2 id="objetivos-especificos-4" tabindex="-1">Objetivos Especificos <a class="header-anchor" href="#objetivos-especificos-4" aria-label="Permalink to &quot;Objetivos Especificos&quot;">​</a></h2><ul><li><p>e Disefar sistemas inteligentes que emulen procesos cognitivos humanos como el razonamiento, la percepcion y el aprendizaje, aplicando modelos computacionales que permitan simular conductas adaptativas en entornos reales <s>.</s></p></li><li><p>e Construir soluciones computacionales orientadas a resolver problematicas en areas cientificas y de ingenieria, mediante el uso de algoritmos inteligentes, redes neuronales, sistemas expertos y agentes autOnomos <s>.</s></p></li><li><p>e Aplicar tecnologias de analisis inteligente de datos, como mineria de datos, aprendizaje automatico y procesamiento de lenguaje natural, para mejorar la toma de decisiones en contextos dinamicos y complejos <s>.</s></p></li><li><p>e Desarrollar aplicaciones de simulacidn que representen el comportamiento de la informacion en escenarios laborales, econdmicos o sociales, facilitando la prediccion, el analisis de tendenciasy la planificacion estratégica <s>.</s></p></li><li><p>e Integrar productos de software inteligentes que puedan interoperar con otros sistemas o gestores de aplicaciones, promoviendo el modularidad, la escalabilidad y la eficiencia en entornos distribuidos</p></li></ul><h2 id="sistematizacion-de-la-linea-dimensiones-operativas-o-programas-3" tabindex="-1">Sistematizacion de la linea (Dimensiones operativas o programas) <a class="header-anchor" href="#sistematizacion-de-la-linea-dimensiones-operativas-o-programas-3" aria-label="Permalink to &quot;Sistematizacion de la linea (Dimensiones operativas o programas)&quot;">​</a></h2><ul><li><p>e Sistemas Recomendadores: emulan el razonamiento de un experto en un dominio concreto y en ocasiones son usados por éstos. Con los sistemas expertos se busca una mejor calidad y rapidez en las respuestas, dando asi lugar a una mejora de la productividad del propio experto al usar este tipo de sistemas informaticos <s>.</s></p></li><li><p>e Mineria de Datos: es una metodologia para detectar o recuperar informacion de un conjunto voluminoso de datos, que por lo general son sistematizados por el individuo, mas no certeramente estructurados, valiendose de técnicas de analisis automaticas que usan herramientas mas complejas, para resolver problemas de diagnosis, clasificaci6n o prediccion, para atacar la imprecision o incertidumbre en los datos <s>.</s></p></li><li><p>e Mineria Web: engloba temas de investigacién en tecnologias de la web, donde la gestion de informacion y conocimiento reportan grandes beneficios en cuanto a: aprendizaje,</p></li></ul><p>3 Gobiemode Venezuela Bolivariano| Ministeriopara la Educaciondel Poser PopularUniversitaria</p><p>UNIVERSIDAD POLITECNICATRUJILLOTERRITORIAL DEL ESTADO (ez “MARIO BRICENO IRAGORRY”</p><p>evaluacion de calidad de ontologias, los sistemas de representacién y busqueda, procesamiento semantico en la web, generacion y uso de repositorios de datos enlazados en la web. También considerada como una metodologia que se encarga de descubrir o extraer informacion potencial, proveniente de sitios web, en los navegadores, enlaces <s>.</s> Dicha metodologia propiamente se subdivide en mineria de contenido, de estructura y de uso web <s>.</s></p><p>e Aprendizaje Automatico (Machine Learning): desarrollo de algoritmos que permiten a los sistemas aprender de los datos y mejorar su rendimiento sin ser explicitamente programados. Incluye aprendizaje supervisado, no supervisadoy por refuerzo, con aplicaciones en prediccion, clasificacién, reconocimiento de patrones y automatizacién de procesos <s>.</s></p><ul><li><p>e Procesamiento de Lenguaje Natural (PLN): area que permite a los sistemas inteligentes comprender, interpretar y generar lenguaje humano <s>.</s> Se aplica en asistentes virtuales, analisis de sentimientos, traduccion automatica, chatbots y extraccion de informacion desde textos <s>.</s></p></li><li><p>e Vision por Computador: disciplina que permite a los sistemas interpretar imagenes y videos, emulando la percepcion visual humana <s>.</s> Se utiliza en reconocimiento facial, analisis biométrico, vehiculos aut6nomos, vigilancia inteligente y diagndstico médico asistido por IA.</p></li><li><p>e Sistemas Multiagente: modelos compuestos por multiples agentes inteligentes que interactuan entre si para resolver problemas complejos de forma colaborativa o competitiva. Se aplican en simulaciones sociales, logistica, robotica distribuida y entornos virtuales.</p></li><li><p>e Computacion Afectiva: area emergente que busca dotar a los sistemas inteligentes de la capacidad de reconocer, interpretar y responder a emociones humanas <s>.</s> Se aplica en educacion personalizada, salud mental digital, interfaces empaticas y experiencias de usuario adaptativas <s>.</s></p></li></ul><p>fe UNVERSDADROLTECMCATERRITORUL DEL ESTADO {YF “MARIO BRICENO IRAGORRY”</p><p>GO cero totaan ceasing,</p><h2 id="linea-de-investigacion-ingenieria-del-software" tabindex="-1">LINEA DE INVESTIGACION: INGENIERIA DEL SOFTWARE <a class="header-anchor" href="#linea-de-investigacion-ingenieria-del-software" aria-label="Permalink to &quot;LINEA DE INVESTIGACION: INGENIERIA DEL SOFTWARE&quot;">​</a></h2><h2 id="objetivo-general-5" tabindex="-1">Objetivo General <a class="header-anchor" href="#objetivo-general-5" aria-label="Permalink to &quot;Objetivo General&quot;">​</a></h2><p>Consolidar conocimientos, metodologias y herramientas orientadas al disenho, desarrollo, evaluacion y mejora de productos de software, promoviendo la innovacion tecnoldgica en todas las etapas del ciclo de vida del software y respondiendo a necesidades reales en contextos organizacionales, educativos, cientificos y sociales</p><h2 id="objetivo-especificos" tabindex="-1">Objetivo Especificos <a class="header-anchor" href="#objetivo-especificos" aria-label="Permalink to &quot;Objetivo Especificos&quot;">​</a></h2><ul><li><p>e Disefar arquitecturas de software robustas y escalables, aplicando patrones de disefo, principios SOLID y modelos de desarrollo orientados a objetos, servicios o componentes.</p></li><li><p>e lImplementar metodologias agiles y tradicionales para la gestion eficiente del ciclo de vida del software, desde el analisis de requerimientos hasta el mantenimiento evolutivo <s>.</s></p></li><li><p>e Desarrollar productos de software que integren criterios de calidad, seguridad, usabilidad y accesibilidad, alineados con estandares internacionales como ISO/IEC 25010.</p></li><li><p>e Aplicar técnicas de modelado de datos, ingenieria de requisitos y pruebas automatizadas, para garantizar la funcionalidad, confiabilidad y rendimiento de las aplicaciones.</p></li><li><p>e Promover la interoperabilidad entre sistemas, mediante el uso de APIs, microservicios, contenedores y tecnologias de integracion continua <s>.</s></p></li><li><p>e Fomentar la investigacidn aplicada en herramientas, entornos y lenguajes de programacion que potencien la productividad y la innovacion en el desarrollo de software.</p></li></ul><h2 id="sistematizacion-de-la-linea-dimensiones-operativas-0-programas-1" tabindex="-1">Sistematizacion de la linea (Dimensiones operativas 0 programas) <a class="header-anchor" href="#sistematizacion-de-la-linea-dimensiones-operativas-0-programas-1" aria-label="Permalink to &quot;Sistematizacion de la linea (Dimensiones operativas 0 programas)&quot;">​</a></h2><ul><li>e Analisis e Ingenieria de MRequerimientos: identificacion, analisis, documentacion, validaci6n y gestidn de las necesidades funcionales y no funcionales de un sistema <s>.</s> Incluye técnicas de elicitacidn, andalisis de</li></ul><p>fe UNVERSDADROLTECMCATERRITORUL DEL ESTADO {YF “MARIO BRICENO IRAGORRY”</p><p>GO cero totaan ceasing,</p><p>consistencia, trazabilidad y especificacion formal, asegurando que el software responda a las expectativas del usuario y se mantenga alineado con los objetivos del proyecto <s>.</s></p><ul><li><p>e Arquitectura y diseno de Software: definicion de estructuras organizativas del sistema, aplicando patrones de _ diseno, principios de modularidad, desacoplamiento y escalabilidad <s>.</s> Incluye arquitecturas monoliticas, orientadas a servicios y basadas en microservicios <s>.</s></p></li><li><p>e Gestion, Calidad y Seguridad del Software: desarrollo de metodologias (agiles y tradicionales), control de calidad, pruebas automatizadas y practicas de desarrollo seguro <s>.</s> Se orienta a mejorar la eficiencia del proceso, la confiabilidad del producto y la proteccion de datos <s>.</s></p></li><li><p>e Ingenieria de Datos y Automatizacion de Procesos: disefo y gestién de modelos de datos, persistencia eficiente, integracion continua y automatizacion de flujos de trabajo <s>.</s> Incluye bases de datos relacionales/no relacionales, DevOps, pipelines de despliegue y analisis de informacion <s>.</s></p></li><li><p>e Interfaces y Experiencia de Usuario (UX/UI): disefo, desarrollo y evaluacion de interfaces de usuario que optimicen la interaccién entre personas y sistemas informaticos <s>.</s> Incluye principios de usabilidad, accesibilidad, disefio centrado en el usuario, prototipado y pruebas de experiencia <s>.</s></p></li></ul>',83)])])}const g=a(n,[["render",r]]);export{u as __pageData,g as default};
